// Verificar título
cy.contains("Tickets").should("be.visible");
// Verificar filtros
cy.contains("Filtros rápidos").should("be.visible");
cy.get(".input-busqueda").should("be.visible");
// Verificar filtros principales
cy.contains("Estado:").should("be.visible");
cy.contains("Prioridad:").should("be.visible");
cy.contains("Activo:").should("be.visible");
cy.contains("Responsable:").should("be.visible");
// Verificar botón Nuevo ticket
cy.contains("Nuevo ticket").should("be.visible");

// Escribir una búsqueda
cy.get(".input-busqueda").type("ticket");
// Verificar que el campo conserva la búsqueda
cy.get(".input-busqueda").should("have.value", "ticket");

// Seleccionar estado Abierto
cy.get(".grupo-filtro").contains("Estado:").parent().find("select").select("ABIERTO");
// Verificar que el filtro quedó seleccionado
cy.get(".grupo-filtro").contains("Estado:").parent().find("select").should("have.value", "ABIERTO");

// Presionar Abierto
cy.contains("button", "Abierto").click();
// Verificar que el botón queda activo
cy.contains("button", "Abierto").should("have.class", "active");
// Presionar En progreso
cy.contains("button", "En progreso").click();
cy.contains("button", "En progreso").should("have.class", "active");
// Presionar Cerrado
cy.contains("button", "Cerrado").click();
cy.contains("button", "Cerrado").should("have.class", "active");

// Verificar si existen tickets cargados
cy.get("body").then($body => {
  if ($body.find(".btn-ver").length > 0) {
    // Abrir el primer ticket
    cy.get(".btn-ver").first().click();
    // Verificar que aparece el modal
    cy.get(".modal-ticket").should("be.visible");
    // Verificar información del ticket
    cy.contains("Activo").should("be.visible");
    cy.contains("Responsable").should("be.visible");
    cy.contains("Solicitante").should("be.visible");
    cy.contains("Descripción").should("be.visible");
    // Cerrar modal
    cy.contains("Cerrar").click();
    // Verificar que el modal desapareció
    cy.get(".modal-ticket").should("not.exist");
  } else {
    // Si no hay tickets, verificar el mensaje correspondiente
    cy.contains("No se encontraron tickets").should("be.visible");
  }
});

// Presionar Nuevo ticket
cy.contains("Nuevo ticket").click();
// Verificar redirección
cy.url({
  timeout: 10000
}).should("include", "/NuevoTicket");
